function aimReplayInit(n,e){
 const length=aimReplayLength(n),start=n.randomStart===true&&length>0?e.rng.range(0,length):0;
 const s=e.behavior.replay={clock:start-Math.max(0,n.delay??0),born:e.bornTick,air:0,fire:1};
 aimReplayPlace(n,e,s);
}
function aimReplayUpdate(n,e,t,i){
 let s=e.behavior.replay;if(!s||!e.alive)return;
 if(s.born!==e.bornTick){aimReplayInit(n,e);s=e.behavior.replay;}
 // Placed first, then the clock moves on: on its spawn tick the bot is at the run's start.
 aimReplayPlace(n,e,s);
 // "stop": like the other bots, it holds still while it shoots, then carries on.
 if(!(n.hold==="stop"&&e.combatHold===1))s.clock+=i*(n.speed??1)*(t.speedScale??1);
}
function aimReplayPlace(n,e,s){
 const f=n.frames,count=Math.floor(f.length/AIM_REPLAY_STRIDE);if(count<1)return;
 const length=aimReplayLength(n);let time=Math.max(0,s.clock);
 if(length<=0)time=0;
 else if(n.playback==="pingpong"){const p=time%(2*length);time=p>length?2*length-p:p;}
 else if(n.playback==="once")time=Math.min(time,length);
 else time%=length;
 const k=time*n.hz,a=Math.min(count-1,Math.floor(k)),b=Math.min(count-1,a+1),w=k-a,A=a*AIM_REPLAY_STRIDE,B=b*AIM_REPLAY_STRIDE;
 e.position={x:f[A]+(f[B]-f[A])*w,y:f[A+1]+(f[B+1]-f[A+1])*w,z:f[A+2]+(f[B+2]-f[A+2])*w};
 const crouch=Math.max(0,Math.min(1,f[A+3]+(f[B+3]-f[A+3])*w));
 // The Studio crouch pose drives the rendered body and hitboxes (see studio-crouch-core).
 e.behavior.studioCrouch={born:e.bornTick,amount:crouch,low:crouch>.5,nextAt:-1,until:-1};
 s.air=f[A+5]===1||f[B+5]===1?1:0;
 s.fire=n.fireWhen==="mine"?(f[A+4]===1||f[B+4]===1?1:0):1;
}
